  dec_proposta -- "Sim" --> dec_modal{"Qual é o verbo modal no comando da questão?"}
  dec_modal -- "Comando usa DEVERIA" --> res_deveria["Gabarito: ERRADO / INCORRETO (Original já era correta)"]
  dec_modal -- "Comando usa PODERIA" --> dec_sentido{"Assertiva respeita a alteração de sentido?"}
  dec_sentido -- "Afirma que mantém o sentido" --> res_sentido_errado["Gabarito: ERRADO / INCORRETO (Muda o referente)"]
  dec_sentido -- "Reconhece mudança ou foca na correção" --> res_poderia_certo["Gabarito: CERTO / CORRETO (Facultatividade válida)"]
